            this.l = l;
            this.r = r;
            this.sum = sum;
        }
    }
​
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();
​
        // 处理输入数据
        // [[1,3,2],[2,5,3],[5,6,2]] => 1,3,2],[2,5,3],[5,6,2
        s = s.substring(2, s.length() - 2);
        String[] parts = s.split("\\],\\[");
​
        List<int[]> tasks = new ArrayList<>();
        for (String part : parts) {
            String[] nums = part.split(",");
            int start = Integer.parseInt(nums[0]);
            int end = Integer.parseInt(nums[1]);
            int p = Integer.parseInt(nums[2]);
            tasks.add(new int[]{start, end, p});
        }
​
        // 按结束时间升序排序
        tasks.sort(Comparator.comparingInt(a -> a[1]));
​
        // 初始化哨兵节点 st存储计算机时机执行任务区间 和 
        List<Interval> st = new ArrayList<>();
        st.add(new Interval(-2, -2, 0));
​
        for (int[] t : tasks) {
            int start = t[0], end = t[1], d = t[2];
​
            // 找到 start 左侧最近的区间
            int idx = st.size() - 1;
            while (idx > 0 && st.get(idx).l >= start) idx--;
            Interval it = st.get(idx);
​
            // 分散执行时间 
            d -= st.get(st.size() - 1).sum - it.sum; // 去掉中间已运行时间
​
            // 去掉重叠当前区间内的运行时间
            if (start <= it.r) {
                d -= it.r - start + 1;
            }
​
            // 全部分散，不会产生新的执行任务区间
            if (d <= 0) continue;
​
            // 合并后缀区间，填满剩余时间 d
            while (end - st.get(st.size() - 1).r <= d) {
                Interval back = st.remove(st.size() - 1);
                d += back.r - back.l + 1;
            }
​
            // 插入新区间
            Interval last = st.get(st.size() - 1);
            st.add(new Interval(end - d + 1, end, last.sum + d));
        }
​
        System.out.println(st.get(st.size() - 1).sum);
    }
}
