rl.on('line', function (s) {
    // [[1,3,2],[2,5,3],[5,6,2]] => 1,3,2],[2,5,3],[5,6,2
    s = s.slice(2, -2);
    let parts = s.split("],[");
    let tasks = parts.map(part => part.split(",").map(Number));
​
    // 按结束时间升序排序
    tasks.sort((a, b) => a[1] - b[1]);
​
    // 初始化哨兵节点
    let st = [new Interval(-2, -2, 0)];
​
    for (let [start, end, d] of tasks) {
        // 找到 start 左侧最近的区间
        let it = st[0];
        for (let i = st.length - 1; i >= 0; i--) {
            if (st[i].l < start) {
                it = st[i];
                break;
            }
        }
​
        // 分散执行时间 
        d -= st[st.length - 1].sum - it.sum;
​
        // 去掉重叠当前区间内的运行时间
        if (start <= it.r) {
            d -= it.r - start + 1;
        }
​
        if (d <= 0) continue;
​
        // 合并后缀区间
        while (end - st[st.length - 1].r <= d) {
            let back = st.pop();
            d += back.r - back.l + 1;
        }
​
        // 插入新区间
        let last = st[st.length - 1];
        st.push(new Interval(end - d + 1, end, last.sum + d));
    }
