import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
// 定义一个结构体表示时间区间
type Interval struct {
    l, r int // 区间左右端点（闭区间）
    sum  int // 执行总工作时间
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    s, _ := reader.ReadString('\n')
    s = strings.TrimSpace(s)
    s = s[2 : len(s)-2] // 去掉 [[ 和 ]]
​
    parts := strings.Split(s, "],[")
    var tasks [][]int
    for _, part := range parts {
        numStrs := strings.Split(part, ",")
        a, _ := strconv.Atoi(numStrs[0])
        b, _ := strconv.Atoi(numStrs[1])
        c, _ := strconv.Atoi(numStrs[2])
        tasks = append(tasks, []int{a, b, c})
    }
​
    // 按结束时间升序排序
    sort.Slice(tasks, func(i, j int) bool {
        return tasks[i][1] < tasks[j][1]
    })
​
    // 初始化哨兵节点
    st := []Interval{{-2, -2, 0}}
​
    for _, t := range tasks {
        start, end, d := t[0], t[1], t[2]
​
        // 找到 start 左侧最近的区间
        it := st[0]
        for i := len(st) - 1; i >= 0; i-- {
            if st[i].l < start {
                it = st[i]
                break
            }
        }
​
        // 分散执行时间
        d -= st[len(st)-1].sum - it.sum
​
        // 去掉重叠当前区间内的运行时间
        if start <= it.r {
            d -= it.r - start + 1
        }
​
        // 全部分散，不会产生新的执行任务区间
        if d <= 0 {
            continue
        }
​
        // 合并后缀区间，填满剩余时间 d
        for end-st[len(st)-1].r <= d {
            back := st[len(st)-1]
            d += back.r - back.l + 1
            st = st[:len(st)-1]
        }
​
        // 插入新区间
        last := st[len(st)-1]
        st = append(st, Interval{end - d + 1, end, last.sum + d})
    }
​
    fmt.Println(st[len(st)-1].sum)
}
